actor ControlledInboxLifecyclePort:SyntheticInboxLifecyclePort {
    nonisolated let grants:[SyntheticInboxLifecycleGrant]
    private var attempts:[InboxLifecycleAttempt]=[]
    private var pending:[Int:CheckedContinuation<SyntheticInboxLifecycleOutcome,any Error>]=[:],waiters:[Int:CheckedContinuation<Void,Never>]=[:]
    init(_ grants:[SyntheticInboxLifecycleGrant]) {self.grants=grants}
    func execute(_ a:InboxLifecycleAttempt) async throws -> SyntheticInboxLifecycleOutcome {let i=attempts.count;attempts.append(a);return try await withCheckedThrowingContinuation {pending[i]=$0;waiters.removeValue(forKey:i)?.resume()}}
    func wait(_ i:Int) async {if pending[i]==nil {await withCheckedContinuation {waiters[i]=$0}}}
    func resolve(_ i:Int,_ value:SyntheticInboxLifecycleOutcome) {pending.removeValue(forKey:i)!.resume(returning:value)}
    func fail(_ i:Int) {pending.removeValue(forKey:i)!.resume(throwing:ReadFailure.unavailable)}
    func recorded()->[InboxLifecycleAttempt] {attempts}
}
