actor ControlledLifecycleRepository:InboxLifecycleRepository {
    private var pending:CheckedContinuation<InboxLifecycleSource,Never>?,waiter:CheckedContinuation<Void,Never>?
    func source(_ c:InboxConversationFilesContext) async throws -> InboxLifecycleSource {await withCheckedContinuation {pending=$0;waiter?.resume();waiter=nil}}
    func wait() async {if pending==nil {await withCheckedContinuation {waiter=$0}}}
    func resolve(_ source:InboxLifecycleSource) {pending!.resume(returning:source);pending=nil}
}
